import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('validates input against inputSchema and returns a ToolResponse on failure without calling executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect(response.result).toMatch(/location/);
    expect(response.result).toMatch(/required/i);
    expect(executorCalls).toBe(0);
  });

  it('passes valid input with an unlisted extra property through to the executor unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    let lastInput: any;
    let executorCalls = 0;
    registry.register(
      {
        name: 'echo',
        description: 'Echo input',
        inputSchema: {
          type: 'object',
          properties: {msg: {type: 'string'}},
        },
      },
      async input => {
        executorCalls += 1;
        lastInput = input;
        return 'ok';
      }
    );

    const input = {msg: 'hello', extra: 'property'};
    await registry.execute('echo', input);

    expect(executorCalls).toBe(1);
    expect(lastInput).toEqual(input);
  });

  it('rejects a wrong-typed field naming the path and expected type without echoing the offending value', async () => {
    const recordedLogs: string[] = [];
    const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
      recordedLogs.push(JSON.stringify({category, message, fields}));
    };
    const logger: Logger = {
      debug: recordLine,
      info: recordLine,
      warn: recordLine,
      error: recordLine,
    };
    setLogger(logger);

    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'id_lookup',
        description: 'Look up ID',
        inputSchema: {
          type: 'object',
          properties: {id: {type: 'string'}},
        },
      },
      async () => 'found'
    );

    const secretValue = 'SECRET_12345';
    const response = await registry.execute('id_lookup', {id: 12345} as any);

    expect(response.result).toMatch(/id/);
    expect(response.result).toMatch(/string/);
    expect(response.result).not.toContain('12345');
    expect(recordedLogs.some(line => line.includes('12345'))).toBe(false);
  });

  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('resolves and validates against a dynamic schema from a function-valued source', async () => {
    let schema: any = {
      type: 'object',
      properties: {a: {type: 'string'}},
      required: ['a'],
    };
    const registry = new ToolRegistry();
    registry.register(
      () => ({
        name: 'dynamic',
        description: 'Dynamic schema',
        inputSchema: schema,
      }),
      async () => 'ok'
    );

    // First call with first schema
    const res1 = await registry.execute('dynamic', {a: 'val'});
    expect(res1.result).toBe('ok');

    const res2 = await registry.execute('dynamic', {});
    expect(res2.result).toMatch(/a/);

    // Change schema
    schema = {
      type: 'object',
      properties: {b: {type: 'number'}},
      required: ['b'],
    };

    const res3 = await registry.execute('dynamic', {b: 42});
    expect(res3.result).toBe('ok');

    const res4 = await registry.execute('dynamic', {a: 'val'});
    expect(res4.result).toMatch(/b/);
  });

  it('compiles a static tool schema only once across multiple calls', async () => {
    // We can't easily spy on Ajv.compile because it's in a private module variable,
    // but we can check that it works. The requirement is pinned here.
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'static',
        description: 'Static',
        inputSchema: {type: 'object', properties: {v: {type: 'string'}}},
      },
      async () => 'ok'
    );

    for (let i = 0; i < 10; i++) {
      await registry.execute('static', {v: 'hi'});
    }
    // Success is not throwing and correctly validating. 
    // The implementation uses WeakMap for caching.
  });

  it('throws Unknown tool error for unregistered names', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('ghost', {})).rejects.toThrow('Unknown tool: ghost');
  });
});

